function isSubsequence(s: string, t: string): boolean {
  // i — сколько символов s уже нашли в t
  let i = 0;

  // Идём по t один раз и «жадно» сопоставляем символы
  for (let j = 0; j < t.length && i < s.length; j++) {
    if (s[i] === t[j]) {
      // Нашли очередной символ s — ищем следующий
      i++;
    }
  }

  // Все символы s найдены по порядку
  return i === s.length;
}

// Время: O(|t|)
// Память: O(1)
